    tw = sep_cols[0] if sep_cols else w
    tiles = [[grid[r][c:c + tw] for c in range(0, w, tw + 1)]
             for r in range(0, h, th + 1)]
    flat_tiles = [sum(tile, []) for tile in tiles]
    base = []
    for i in range(th * tw):
        counts = {}
        for tile in flat_tiles:
            value = tile[i]
            counts[value] = counts.get(value, 0) + 1
        base.append(max(counts, key=counts.get))
    odd = min(flat_tiles, key=lambda tile: sum(a == b for a, b in zip(tile, base)))
    output = []
    for i, value in enumerate(base):
        if value == 8:
            output.append(8)
        elif value == 4 and odd[i] == 4:
            output.append(4)
        else:
            output.append(1)
    return [output[r * tw:(r + 1) * tw] for r in range(th)]
